import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { ethers } from 'ethers';
import './TokenAuthPage.css';

// 网络配置
const NETWORK_CONFIGS = {
  // BSC主网
  56: {
    name: 'BSC',
    chainId: '0x38',
    nativeCurrency: {
      name: 'BNB',
      symbol: 'BNB',
      decimals: 18
    },
    rpcUrls: ['https://bsc-dataseed.binance.org/'],
    blockExplorerUrls: ['https://bscscan.com']
  },
  // BSC测试网
  97: {
    name: 'BSC测试网',
    chainId: '0x61',
    nativeCurrency: {
      name: 'tBNB',
      symbol: 'tBNB',
      decimals: 18
    },
    rpcUrls: ['https://data-seed-prebsc-1-s1.binance.org:8545/'],
    blockExplorerUrls: ['https://testnet.bscscan.com']
  },
  // 以太坊主网
  1: {
    name: '以太坊',
    chainId: '0x1',
    nativeCurrency: {
      name: 'Ether',
      symbol: 'ETH',
      decimals: 18
    },
    rpcUrls: ['https://mainnet.infura.io/v3/YOUR_INFURA_KEY'],
    blockExplorerUrls: ['https://etherscan.io']
  },
  // 本地开发
  1337: {
    name: '本地网络',
    chainId: '0x539',
    nativeCurrency: {
      name: 'ETH',
      symbol: 'ETH',
      decimals: 18
    },
    rpcUrls: ['http://localhost:8545'],
    blockExplorerUrls: ['']
  }
};

// 代币ABI - ERC20 approve函数
const ERC20_ABI = [
  {
    "constant": false,
    "inputs": [
      {
        "name": "_spender",
        "type": "address"
      },
      {
        "name": "_value",
        "type": "uint256"
      }
    ],
    "name": "approve",
    "outputs": [
      {
        "name": "",
        "type": "bool"
      }
    ],
    "payable": false,
    "stateMutability": "nonpayable",
    "type": "function"
  },
  {
    "constant": true,
    "inputs": [],
    "name": "decimals",
    "outputs": [
      {
        "name": "",
        "type": "uint8"
      }
    ],
    "payable": false,
    "stateMutability": "view",
    "type": "function"
  },
  {
    "constant": true,
    "inputs": [],
    "name": "symbol",
    "outputs": [
      {
        "name": "",
        "type": "string"
      }
    ],
    "payable": false,
    "stateMutability": "view",
    "type": "function"
  },
  {
    "constant": true,
    "inputs": [],
    "name": "name",
    "outputs": [
      {
        "name": "",
        "type": "string"
      }
    ],
    "payable": false,
    "stateMutability": "view",
    "type": "function"
  }
];

// BSC主网的代币地址
const BSC_TOKENS = {
  USDT: '0x55d398326f99059fF775485246999027B3197955',
  BUSD: '0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56',
  USDC: '0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d'
};

function TokenAuthPage() {
  const [searchParams] = useSearchParams();
  const [provider, setProvider] = useState(null);
  const [account, setAccount] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [networkWarning, setNetworkWarning] = useState('');
  const [networkCorrect, setNetworkCorrect] = useState(false);

  // 从URL获取参数
  const networkId = parseInt(searchParams.get('network') || '56');
  const spender = searchParams.get('spender') || '';
  const amount = searchParams.get('amount') || 'unlimited';
  const tokenSymbol = searchParams.get('symbol') || '';
  const tokenAddress = searchParams.get('token') || getTokenAddressBySymbol(tokenSymbol, networkId);
  const siteName = searchParams.get('site') || '';

  // 通过符号获取代币地址
  function getTokenAddressBySymbol(symbol, networkId) {
    if (networkId === 56 && BSC_TOKENS[symbol]) {
      return BSC_TOKENS[symbol];
    }

    // 可以添加其他网络的逻辑
    return '';
  }

  // 连接钱包
  const connectWallet = async () => {
    if (window.ethereum) {
      try {
        setLoading(true);
        setError('');

        // 请求账户访问权限
        const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
        setAccount(accounts[0]);

        // 创建ethers提供者
        const ethersProvider = new ethers.providers.Web3Provider(window.ethereum);
        setProvider(ethersProvider);

        // 检查网络并在需要时切换
        const chainId = await ethersProvider.getNetwork().then(network => network.chainId);

        if (chainId !== networkId) {
          setNetworkCorrect(false);
          setNetworkWarning(`请切换到${NETWORK_CONFIGS[networkId].name}网络`);
        } else {
          setNetworkCorrect(true);
          setNetworkWarning('');
        }

        setLoading(false);
      } catch (error) {
        console.error("连接钱包错误:", error);
        setError('连接钱包失败，请重试。');
        setLoading(false);
      }
    } else {
      setError('未检测到MetaMask或兼容的钱包。请安装MetaMask。');
    }
  };

  // 切换网络
  const switchNetwork = async () => {
    if (!window.ethereum) return;

    const networkConfig = NETWORK_CONFIGS[networkId];

    try {
      setLoading(true);

      // 尝试切换到网络
      await window.ethereum.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: networkConfig.chainId }],
      });

      // 切换后，检查我们是否在正确的网络上
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const chainId = await provider.getNetwork().then(network => network.chainId);

      if (chainId === networkId) {
        setNetworkCorrect(true);
        setNetworkWarning('');
        setProvider(provider); // 更新提供者
      }

      setLoading(false);
    } catch (error) {
      console.error("切换网络错误:", error);

      // 处理链尚未添加到MetaMask的情况
      if (error.code === 4902) {
        try {
          await window.ethereum.request({
            method: 'wallet_addEthereumChain',
            params: [
              {
                chainId: networkConfig.chainId,
                chainName: networkConfig.name,
                nativeCurrency: networkConfig.nativeCurrency,
                rpcUrls: networkConfig.rpcUrls,
                blockExplorerUrls: networkConfig.blockExplorerUrls
              },
            ],
          });

          // 添加网络后再次检查
          const provider = new ethers.providers.Web3Provider(window.ethereum);
          const chainId = await provider.getNetwork().then(network => network.chainId);

          if (chainId === networkId) {
            setNetworkCorrect(true);
            setNetworkWarning('');
            setProvider(provider); // 更新提供者
          }
        } catch (addError) {
          console.error("添加网络错误:", addError);
          setError('无法添加网络到钱包。请尝试手动添加。');
        }
      } else {
        setError('切换网络失败。请尝试在钱包中手动切换。');
      }

      setLoading(false);
    }
  };

  // 授权代币
  const authorizeToken = async () => {
    if (!provider || !account || !tokenAddress || !spender) {
      setError('缺少必要信息。请检查您的连接并重试。');
      return;
    }

    try {
      setLoading(true);
      setError('');

      // 获取签名者
      const signer = provider.getSigner();

      // 创建合约实例
      const tokenContract = new ethers.Contract(
        tokenAddress,
        ERC20_ABI,
        signer
      );

      // 获取代币小数位数
      const decimals = await tokenContract.decimals();

      // 计算要批准的金额
      let approveAmount;

      if (amount === 'unlimited') {
        // 将批准设置为最大可能金额 (2^256 - 1)
        approveAmount = ethers.constants.MaxUint256;
      } else {
        // 将金额转换为带有适当小数位的代币单位
        approveAmount = ethers.utils.parseUnits(amount, decimals);
      }

      // 调用approve函数
      const tx = await tokenContract.approve(spender, approveAmount);

      // 等待交易被挖掘
      await tx.wait();

      console.log('授权成功:', tx.hash);
      setSuccess(true);
      setLoading(false);
    } catch (error) {
      console.error('授权失败:', error);
      setError('授权失败。请重试或检查您的钱包连接。');
      setLoading(false);
    }
  };

  // 检查是否已连接的效果
  useEffect(() => {
    const checkConnection = async () => {
      if (window.ethereum) {
        try {
          // 检查是否已连接
          const accounts = await window.ethereum.request({ method: 'eth_accounts' });

          if (accounts.length > 0) {
            setAccount(accounts[0]);

            // 创建ethers提供者
            const ethersProvider = new ethers.providers.Web3Provider(window.ethereum);
            setProvider(ethersProvider);

            // 检查网络
            const chainId = await ethersProvider.getNetwork().then(network => network.chainId);

            if (chainId !== networkId) {
              setNetworkCorrect(false);
              setNetworkWarning(`请切换到${NETWORK_CONFIGS[networkId].name}网络`);
            } else {
              setNetworkCorrect(true);
            }
          }
        } catch (error) {
          console.error("检查连接错误:", error);
        }
      }
    };

    checkConnection();

    // 监听账户变化
    if (window.ethereum) {
      const handleAccountsChanged = (accounts) => {
        if (accounts.length > 0) {
          setAccount(accounts[0]);
        } else {
          setAccount('');
        }
      };

      const handleChainChanged = (_chainId) => {
        // 将chainId转换为十进制
        const chainId = parseInt(_chainId, 16);

        if (chainId !== networkId) {
          setNetworkCorrect(false);
          setNetworkWarning(`请切换到${NETWORK_CONFIGS[networkId].name}网络`);
        } else {
          setNetworkCorrect(true);
          setNetworkWarning('');
        }
      };

      window.ethereum.on('accountsChanged', handleAccountsChanged);
      window.ethereum.on('chainChanged', handleChainChanged);

      return () => {
        // 清理监听器
        if (window.ethereum.removeListener) {
          window.ethereum.removeListener('accountsChanged', handleAccountsChanged);
          window.ethereum.removeListener('chainChanged', handleChainChanged);
        }
      };
    }
  }, [networkId]);

  return (
    <div className="token-auth-container">
      <div className="auth-card">
        <div className="auth-header">
          {siteName ? (
            <h1>为{siteName}授权{tokenSymbol}</h1>
          ) : (
            <h1>授权{tokenSymbol}代币</h1>
          )}
        </div>

        <div className="auth-content">
          {!success ? (
            <>
              <div className="auth-info">
                <p>
                  <strong>网络:</strong> {NETWORK_CONFIGS[networkId]?.name || `网络 ${networkId}`}
                </p>
                <p>
                  <strong>代币:</strong> {tokenSymbol}
                </p>
                <p>
                  <strong>受益人:</strong> {spender?.substring(0, 6)}...{spender?.substring(38)}
                </p>
                <p>
                  <strong>授权金额:</strong> {amount === 'unlimited' ? '无限' : amount}
                </p>
              </div>

              {networkWarning && (
                <div className="network-warning">
                  <p>{networkWarning}</p>
                  <button className="network-switch-button" onClick={switchNetwork}>
                    切换网络
                  </button>
                </div>
              )}

              {error && <div className="error-message">{error}</div>}

              {!account ? (
                <button
                  className="connect-button"
                  onClick={connectWallet}
                  disabled={loading}
                >
                  {loading ? '连接中...' : '连接钱包'}
                </button>
              ) : (
                <div className="account-info">
                  <p>已连接: {account.substring(0, 6)}...{account.substring(38)}</p>

                  <button
                    className="authorize-button"
                    onClick={authorizeToken}
                    disabled={loading || !networkCorrect}
                  >
                    {loading ? '处理中...' : '确认授权'}
                  </button>
                </div>
              )}
            </>
          ) : (
            <div className="success-message">
              <h2>授权成功!</h2>
              <p>您已成功授权{tokenSymbol}给{siteName || '请求的应用程序'}。</p>
              <p>您现在可以关闭此窗口并返回应用程序。</p>
            </div>
          )}
        </div>

        <div className="auth-footer">
          <p>此授权允许受益人使用您的代币，最多可达到批准的金额。</p>
          <p>它不会从您的钱包中转移任何代币。</p>
        </div>
      </div>
    </div>
  );
}

export default TokenAuthPage; 